'use strict';
const paperFigure=(file,label)=>`<details class="paper-figure"><summary>${label}</summary><img src="assets/${file}" alt="Original paper figure: ${label}"></details>`;
window.paperScene=function(work,stage){
 if(work===1){
 const k='<p class="edits-kicker">STYLING AND TRUST</p>';
 if(stage===0)return k+`<div class="styling-flow"><div>Original text</div><span>→</span><div class="style-core">AI styling</div><span>→</span><div>Changed cues</div></div><div class="task-grid"><span>Emotion inference<br><strong>Privacy question</strong></span><span>Misinformation detection<br><strong>Security question</strong></span></div><p class="edits-note">Apple Intelligence, Microsoft Copilot and Qwen are evaluated alongside open-model baselines. A polished rewrite can change what a detector infers.</p>${paperFigure('styling-overview.png','View the study design')}`;
 if(stage===1)return k+`<div class="edit-options" aria-label="Choose writing style">${['Rewrite','Professional','Friendly','Concise'].map((x,i)=>`<button data-style="${i}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><div id="styling-metrics"></div><p class="edits-note">PPR: relative emotion-classifier accuracy drop, not anonymity. LFR: fake-news label flips. Apple Intelligence; different datasets and metrics.</p>${paperFigure('styling-privacy.png','View privacy results')}${paperFigure('styling-evasion.png','View evasion results')}`;
 return k+`<div class="edit-options"><button data-adapt="0" aria-pressed="true">Original training</button><button data-adapt="1" aria-pressed="false">Add stylized training data</button></div><div id="adapt-result" class="adapt-result"><strong>Styling changes the detector’s input</strong><p>Models trained on original text can be less reliable on styled text.</p></div><p class="edits-note">The study’s augmentation experiments generally reduce both privacy protection rate and fake-news label flipping: a security benefit can also restore sensitive emotion inference. Directional summary, not a universal guarantee.</p>`;
 }
 const k='<p class="edits-kicker">SENSOR–TEXT ALIGNMENT</p>';
 if(stage===0)return k+`<div class="edit-options"><button data-align="0" aria-pressed="true">Before perturbation</button><button data-align="1" aria-pressed="false">Text-side perturbation</button></div><svg class="alignment-map" viewBox="0 0 500 150" role="img" aria-label="Conceptual shared embedding space: sensor point stays fixed while text point moves"><path d="M25 125H475M35 135V15" stroke="#ffffff30" fill="none"/><path d="M55 50l15-15 15 32 15-48 15 50 15-20 15 1" stroke="#e5bf8b" fill="none" stroke-width="3"/><text x="55" y="90">Unchanged sensor input</text><line class="alignment-link" x1="285" y1="75" x2="315" y2="60" stroke="#dbc0cb" stroke-dasharray="5 4"/><circle cx="285" cy="75" r="10" fill="#e5bf8b"/><text x="250" y="110">Sensor</text><g class="text-point"><circle cx="315" cy="60" r="10" fill="#d59bb0"/><text x="323" y="48">Text</text></g></svg><p class="edits-note">Conceptual illustration, not measured coordinates. Only the text embedding is modified; sensor readings and model parameters remain unchanged.</p>`;
 if(stage===1)return k+`<div class="styling-flow"><div>Sensor MLP</div><span>↔</span><div><b>64D</b><br>shared space</div><span>↔</span><div>DistilBERT</div></div><div class="task-grid"><span>WISDM · motion</span><span>MotionSense · motion</span><span>HHAR · motion</span><span>WESAD · physiology</span></div><p class="edits-note">A compromised inference pipeline introduces bounded text-embedding perturbations. This is not label poisoning, sensor tampering, or an experiment on LLM reasoning.</p>${paperFigure('sensor-architecture.png','View the attack architecture')}`;
 return k+`<label class="activity-select">WISDM activity <select id="sensor-activity">${['Downstairs','Jogging','Sitting','Upstairs','Standing','Walking'].map((x,i)=>`<option value="${i}">${x}</option>`).join('')}</select></label><div class="threshold-result"><span>Reported first successful perturbation budget</span><strong id="epsilon-value">ε = 0.5</strong><div class="bar-track"><div id="epsilon-bar" style="width:12.5%"></div></div><small>Embedding budget ε, not a percentage or accuracy</small></div><p class="edits-note">Sensitivity varies by activity (Figure 5). The paper also reports weak clean positive/negative pair separation; these results do not establish a robust classifier or a validated defense.</p>`;
};
window.bindPaperScene=function(work,stage,scene,pause){
 scene.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)pause()}));
 function controls(attr,fn){scene.querySelectorAll('['+attr+']').forEach(b=>b.addEventListener('click',()=>{pause();scene.querySelectorAll('['+attr+']').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));fn(Number(b.getAttribute(attr)))}));}
 if(work===1&&stage===1){const privacy=[29.65,49.79,48.91,21.31],evasion=[34,62,48,40];function chart(i){scene.querySelector('#styling-metrics').innerHTML=[['Emotion inference · Dair-AI','Privacy protection rate',privacy[i]],['Fake-news detection · ISOT','Label-flipping rate',evasion[i]]].map(([a,b,n])=>`<div class="style-metric"><span>${a}</span><div><strong>${b}</strong><b>${n}%</b></div><div class="bar-track"><div style="width:${n}%"></div></div></div>`).join('')};chart(0);controls('data-style',chart);}
 if(work===1&&stage===2)controls('data-adapt',i=>{scene.querySelector('#adapt-result').innerHTML=i?'<strong>Detectors learn from styled examples</strong><p>↓ Fake-news evasion<br>↓ Emotion privacy protection</p>':'<strong>Styling changes the detector’s input</strong><p>Models trained on original text can be less reliable on styled text.</p>';});
 if(work===3&&stage===0)controls('data-align',i=>{scene.querySelector('.text-point').style.transform=i?'translate(115px,40px)':'translate(0,0)';scene.querySelector('.alignment-link').setAttribute('x2',i?'430':'315');scene.querySelector('.alignment-link').setAttribute('y2',i?'100':'60');});
 const select=scene.querySelector('#sensor-activity');if(select)select.addEventListener('change',()=>{pause();const n=[.5,1,3,3,4,4][Number(select.value)];scene.querySelector('#epsilon-value').textContent='ε = '+n;scene.querySelector('#epsilon-bar').style.width=n/4*100+'%';});
};
